        void SendTask() {string text=draft.Text.Trim();if(text.Length==0)return;if(text.Length>32768)throw new Exception("任务文字过长");if(queue.Count>=16)throw new Exception("等待队列已满");var aiOptions=AiSettings.Options(vault);if(J.Str(aiOptions,"model").Length==0||Agent.NeedsKey(aiOptions)&&J.Str(aiOptions,"key").Length==0||J.Str(aiOptions,"provider")=="chatgpt"&&!ChatGPTAuth.PlanEnabled(chatAuth.Selected)){Navigate("settings");return;}var selected=target.SelectedItem as Choice;var request=new QueuedTask{Chat=chat,Project=project,Text=text,Target=selected==null?"local":selected.Id,Attachments=attachments.ToList(),Automatic=automatic.Checked};draft.Clear();chat["draft"]="";chat["attachments"]=new object[0];attachments.Clear();RenderAttachments();if(job!=null){queue.Enqueue(request);Append(chat,"队列",text);taskStatus.Text=T("已加入等待队列")+" · "+queue.Count;}else RunTask(request);}
        async void RunTask(QueuedTask request) {TrackMcpJob();job=new CancellationTokenSource();var token=job.Token;var currentAgent=agent;workingDirectory=J.Str(request.Project,"workspace",J.Str(vault.State,"workspace"));if(string.IsNullOrWhiteSpace(workingDirectory))workingDirectory=J.Str(vault.State,"workspace");Dictionary<string,object> options=AiSettings.Options(vault);List<object> activeHistory=null;try{if(J.Bool(request.Chat,"autoTitle",J.Str(request.Chat,"name")=="新会话")){request.Chat["autoTitle"]=false;request.Chat["name"]=request.Text.Length>22?request.Text.Substring(0,22)+"…":request.Text;FillTree();}var history=J.List(J.Get(request.Chat,"history"));activeHistory=history;history.AddRange(Agent.Input(request.Text,request.Attachments));request.Chat["history"]=J.Parse(J.Write(history));Append(request.Chat,"你",request.Text+(request.Attachments.Count>0?"\n["+string.Join(", ",request.Attachments.Select(x=>J.Str(x,"name")))+"]":""));currentAgent.Event=(kind,text)=>Ui(()=>{TrackMcpEvent(kind,text);if(kind=="流式回复"){if(request.Chat==chat&&page=="chat"){timeline.SetPreview(T("助手"),text);}}else if(kind=="状态"){if(taskStatus!=null&&!taskStatus.IsDisposed)taskStatus.Text=T(text);}else Append(request.Chat,kind,text);});currentAgent.Approve=(name,args,targetId,ct)=>request.Automatic?Task.FromResult(true):Permission(name,args,targetId,ct);if(page=="chat"){send.Text=T("加入队列");stopButton.Enabled=true;}await Task.Run(()=>currentAgent.Run(history,options,request.Target,token),token);request.Chat["history"]=history;Append(request.Chat,"状态",T("任务结束"));}catch(Exception e){Append(request.Chat,token.IsCancellationRequested?"状态":"错误",token.IsCancellationRequested?T("已停止"):J.Error(e));}finally{if(activeHistory!=null){Agent.CompleteInterruptedCalls(activeHistory);request.Chat["history"]=activeHistory;}store.Save();job.Dispose();job=null;workingDirectory="";if(page=="chat"){send.Text=T("发送");stopButton.Enabled=false;taskStatus.Text=T("就绪");}if(queue.Count>0)RunTask(queue.Dequeue());}}
        Task<bool> Permission(string tool,object args,string targetId,CancellationToken ct) {var result=new TaskCompletionSource<bool>();Ui(()=>{if(ct.IsCancellationRequested){result.TrySetResult(false);return;}using(var f=new Form{Icon=Icon,Text=T("操作确认"),Size=new Size(560,430),StartPosition=FormStartPosition.CenterParent,Font=Font,MinimizeBox=false,MaximizeBox=false}){var title=L(T("执行目标")+": "+(targetId=="local"?T("本机"):J.Str(hub.Peer(targetId),"name")),12,true);title.Dock=DockStyle.Top;var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Text=tool+Environment.NewLine+J.Write(args),Font=new Font("Consolas",10),WordWrap=true};var row=Flow();row.Dock=DockStyle.Bottom;row.Height=48;row.AutoSize=false;row.Controls.Add(B("允许一次",()=>{result.TrySetResult(true);f.Close();},true,120));row.Controls.Add(B("拒绝",()=>{result.TrySetResult(false);f.Close();},false,120));f.Controls.Add(text);f.Controls.Add(row);f.Controls.Add(title);f.FormClosed+=(s,e)=>result.TrySetResult(false);using(ct.Register(()=>Ui(()=>f.Close()))){Design.ApplyTheme(f);f.ShowDialog(this);}}});return result.Task;}
